function aufgabe(r: Redaktion, art: "funktion" | "anwendung", index: number): DachAufgabe {
  const texte = art === "funktion" ? r.funktionAntworten : r.massnahmen;
  const optionen = texte.map((text, i) => ({ id: `o${i + 1}`, text, korrekt: i === 0 }));
  const versatz = (index + (art === "anwendung" ? 2 : 0)) % optionen.length;
  return { id: `dach3d-${r.id}-${art}`, version: 1, detailId: r.id,
    titel: art === "funktion" ? `${r.titel}: die Funktion` : `${r.titel}: richtig handeln`,
    frage: art === "funktion" ? `Welche Aussage beschreibt die Aufgabe von „${r.titel}“ im dargestellten Lehrmodell richtig?` : `${r.fehler} Welche Maßnahme passt zu diesem Befund?`,
    optionen: [...optionen.slice(versatz), ...optionen.slice(0, versatz)],
    erklaerung: art === "funktion" ? r.funktion : `${r.korrektur} ${r.gut}`,
    lernzielIds: [`dach3d-${r.id}`], ansicht: art === "funktion" ? "nah" : "schnitt" };
}

export const DACH_DETAILS: DachDetail[] = REDAKTION.map((r, i) => ({
  id: r.id, version: 1, titel: r.titel, gruppe: r.gruppe, formen: [...r.formen], lfIds: [...r.lf], lernzielIds: [`dach3d-${r.id}`],
  funktion: r.funktion, aufbau: [...r.aufbau], bauteile: r.teile.map(([id, name, funktion]) => ({ id: `${r.id}-${id}`, name, funktion })),
  schritte: r.montage.map(([titel, handlung, warum, kontrolle, ansicht], n) => ({ id: `${r.id}-schritt-${n + 1}`, titel, handlung, warum, kontrolle, ansicht: ansicht ?? "nah" })),
  kontrolle: { richtig: r.gut, fehler: r.fehler, korrektur: r.korrektur, kriterien: [...r.kriterien] },
  aufgaben: [aufgabe(r, "funktion", i), aufgabe(r, "anwendung", i)], werkstattIds: r.werkstatt ?? [],
  quellen: ["Eigene herstellerneutrale Lehrdarstellung, Inhaltsversion 1; fachliche Zuordnung nach den vorhandenen Lernfeldern der App.", `Fachlicher Bezug: ${r.lf.join(", ")}.`, "Für eine tatsächliche Ausführung gelten die zum gewählten Produkt und Aufbau gehörende Planung, Verlegeunterlagen und Arbeitsanweisung. Die Darstellung enthält keine allgemeine Bemessung oder Herstellerfreigabe."],
}));

export function getDachDetail(id: string): DachDetail | undefined { return DACH_DETAILS.find(d => d.id === id); }
export function dachDetailsFuer(form: DachForm): DachDetail[] { return DACH_DETAILS.filter(d => d.formen.includes(form)); }
